referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const sorted = d.elements
    .map((x, i) => ({ ...x, i }))
    .sort((a, b) => a.top - b.top || a.left - b.left || a.i - b.i);
  const out = [];
  for (let i = 0; i < sorted.length; ) {
    let j = i + 1;
    while (j < sorted.length && sorted[j].top - sorted[i].top <= d.tolerance) j++;
    const row = sorted.slice(i, j).sort((a, b) => a.left - b.left || a.top - b.top || a.i - b.i);
    out.push(...row.map((x) => x.id));
    i = j;
  }
  return out;
}

