type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const sorted = d.elements
    .map((x: any, i: number) => ({ ...x, i }))
    .sort((a: any, b: any) => a.top - b.top || a.left - b.left || a.i - b.i);
  const out: string[] = [];
  for (let i = 0; i < sorted.length; ) {
    let j = i + 1;
    while (j < sorted.length && sorted[j].top - sorted[i].top <= d.tolerance) j++;
    const row = sorted
      .slice(i, j)
      .sort((a: any, b: any) => a.left - b.left || a.top - b.top || a.i - b.i);
    out.push(...row.map((x: any) => x.id));
    i = j;
  }
  return out;
}
